namespace BancoBrasil;
require_once __DIR__.'/ApiAbatement.php';
require_once __DIR__.'/ApiAddress.php';require_once __DIR__.'/ApiOwnNumber.php';require_once __DIR__.'/ApiDiscountAmendment.php';require_once __DIR__.'/ApiDiscountCancellation.php';require_once __DIR__.'/ApiDiscountAssignment.php';require_once __DIR__.'/ApiReceiptWindow.php';
/** First financial application requires every write to be independently resolved by its exact typed contract. */
final class ApiFinancialMutationFence
{
    private static function addressMatches(array$result,string$hash):bool{try{return is_array($result['bank_address']??null)&&hash_equals(ApiAddress::addressHash($result['bank_address']),$hash);}catch(\Throwable$error){return false;}}
    private static function rows($db,string$sql,array$args=[]):array{return \IssuerStorage::query($db,$sql,$args)->result_array();}
    public static function assertResolvedInOwned($db,string$p,int$origin,array$financialQuery,array$financialResult):void
    {
        \IssuerTransaction::assertOwned($db,$p,['bb_api_operations','bb_origins','bb_api_origins']);$writes=self::rows($db,"SELECT * FROM {$p}bb_api_operations WHERE origin_id=? AND operation NOT IN ('issue','query','movements') ORDER BY id FOR UPDATE",[$origin]);$confirmed=[];$latest=[];$referenceAlias=null;$referenceAliases=[];
        foreach($writes as$write){
            if(in_array($write['status'],['rejected','auth_failed'],true))continue;$kind=$write['operation'];if(!in_array($kind,['amend_due','amend_abat','amend_addr','amend_ref','amend_disc','amend_win','clear_disc','add_disc'],true)||$write['status']!=='confirmed')throw new \DomainException('bb_api_credit_mutation_requires_review');$data=json_decode($write['result_json'],true,32,JSON_THROW_ON_ERROR);if(!preg_match('/^[a-f0-9]{64}$/D',$data['account_evidence_hash']??''))throw new \DomainException('bb_api_credit_mutation_requires_review');
            if($kind==='amend_due'){$value=$data['amendment']['due_date']??null;if(($data['bank_state']??null)!=='amendment_confirmed'||!is_string($value))throw new \DomainException('bb_api_credit_mutation_requires_review');try{Fields::date($value);}catch(\Throwable$error){throw new \DomainException('bb_api_credit_mutation_requires_review');}$idField='amendment_id';$valueField='bank_due_date';}
            elseif(in_array($kind,['amend_disc','clear_disc','add_disc'],true)){
                try{$class=match($kind){'clear_disc'=>ApiDiscountCancellation::class,'add_disc'=>ApiDiscountAssignment::class,default=>ApiDiscountAmendment::class};$intent=$class::input($data['discount_instruction']??[]);$source=self::rows($db,"SELECT o.*,a.snapshot_json FROM {$p}bb_origins o JOIN {$p}bb_api_origins a ON a.origin_id=o.id WHERE o.id=? FOR UPDATE",[$origin])[0]??[];$snapshot=json_decode($source['snapshot_json']??'',true,32,JSON_THROW_ON_ERROR);if(($data['bank_state']??null)!=='discount_confirmed'||($data['discount_contract']??null)!==$class::CONTRACT||!hash_equals($class::fingerprint($source,$snapshot,$intent),$data['discount_fingerprint']??''))throw new \DomainException();$value=$class::hash($intent);}catch(\Throwable$error){throw new \DomainException('bb_api_credit_mutation_requires_review');}$idField='discount_id';$valueField='bank_discount_offer_hash';
            }
            elseif($kind==='amend_ref'){
                try{$intent=ApiOwnNumber::input($data['reference_instruction']??[]);$source=self::rows($db,"SELECT o.*,a.snapshot_json FROM {$p}bb_origins o JOIN {$p}bb_api_origins a ON a.origin_id=o.id WHERE o.id=? FOR UPDATE",[$origin])[0]??[];$snapshot=json_decode($source['snapshot_json']??'',true,32,JSON_THROW_ON_ERROR);if(($data['bank_state']??null)!=='reference_confirmed'||($data['reference_contract']??null)!==ApiOwnNumber::CONTRACT||!hash_equals(ApiOwnNumber::fingerprint($source,$snapshot,$intent),$data['reference_fingerprint']??''))throw new \DomainException();if($referenceAlias===null){$referenceAlias='CRM'.$source['invoice_id'];$referenceAliases=[$referenceAlias];}if($intent['previous_reference']!==$referenceAlias||in_array($intent['new_reference'],$referenceAliases,true))throw new \DomainException();$referenceAlias=$intent['new_reference'];$referenceAliases[]=$referenceAlias;$value=$intent['new_reference'];}catch(\Throwable$error){throw new \DomainException('bb_api_credit_mutation_requires_review');}$idField='reference_id';$valueField='bank_own_number';
            }
            elseif($kind==='amend_win'){
                try{$intent=ApiReceiptWindow::input($data['window_instruction']??[]);$source=self::rows($db,"SELECT o.*,a.snapshot_json FROM {$p}bb_origins o JOIN {$p}bb_api_origins a ON a.origin_id=o.id WHERE o.id=? FOR UPDATE",[$origin])[0]??[];$snapshot=json_decode($source['snapshot_json']??'',true,32,JSON_THROW_ON_ERROR);if(($data['bank_state']??null)!=='window_confirmed'||($data['window_contract']??null)!==ApiReceiptWindow::CONTRACT||!hash_equals(ApiReceiptWindow::fingerprint($source,$snapshot,$intent),$data['window_fingerprint']??''))throw new \DomainException();$value=$intent['days'];}catch(\Throwable$error){throw new \DomainException('bb_api_credit_mutation_requires_review');}$idField='window_id';$valueField='bank_receipt_window_days';
            }
            else{
                $address=$kind==='amend_addr';$contract=$address?ApiAddress::class:ApiAbatement::class;$intentField=$address?'address_instruction':'abatement';$contractField=$address?'address_contract':'abatement_contract';$fingerprintField=$address?'address_fingerprint':'abatement_fingerprint';
                try{$intent=$contract::input($data[$intentField]??[]);$source=self::rows($db,"SELECT o.*,a.snapshot_json FROM {$p}bb_origins o JOIN {$p}bb_api_origins a ON a.origin_id=o.id WHERE o.id=? FOR UPDATE",[$origin])[0]??[];$snapshot=json_decode($source['snapshot_json']??'',true,32,JSON_THROW_ON_ERROR);if(($data['bank_state']??null)!==($address?'address_confirmed':'abatement_confirmed')||($data[$contractField]??null)!==$contract::CONTRACT||!hash_equals($contract::fingerprint($source,$snapshot,$intent),$data[$fingerprintField]??''))throw new \DomainException();$value=$address?ApiAddress::addressHash($intent):$intent['amount'];}catch(\Throwable$error){throw new \DomainException('bb_api_credit_mutation_requires_review');}$idField=$address?'address_id':'abatement_id';$valueField=$address?'bank_address_hash':'bank_abatement_amount';
            }
            $id=(int)$write['id'];$confirmed[$id]=['kind'=>$kind,'value'=>$value,'id_field'=>$idField,'value_field'=>$valueField,'hash'=>$data['account_evidence_hash'],'proved'=>false,'intent'=>in_array($kind,['amend_disc','clear_disc','add_disc'],true)?$intent:null,'class'=>in_array($kind,['amend_disc','clear_disc','add_disc'],true)?$class:null];$latest[in_array($kind,['amend_disc','clear_disc','add_disc'],true)?'discount':$kind]=$id;
        }
        if(!$confirmed)return;
        foreach(self::rows($db,"SELECT id,http_status,response_hash,result_json FROM {$p}bb_api_operations WHERE origin_id=? AND operation='query' AND status='validated' FOR UPDATE",[$origin])as$query){$result=json_decode($query['result_json'],true,32,JSON_THROW_ON_ERROR);foreach(['amendment_id','abatement_id','address_id','discount_id','window_id','reference_id']as$idField){$id=(int)($result[$idField]??0);if(!isset($confirmed[$id])||$confirmed[$id]['id_field']!==$idField)continue;$proof=$confirmed[$id];$matched=(int)$query['id']>$id&&(int)$query['http_status']===200&&preg_match('/^[a-f0-9]{64}$/D',$query['response_hash'])&&($result['account_scope_confirmed']??null)==='1'&&($result['account_evidence_hash']??null)===$proof['hash']&&($result[$proof['value_field']]??null)===$proof['value'];if($proof['kind']==='amend_due')$matched=$matched&&($result['dataVencimentoTituloCobranca']??null)===(new \DateTimeImmutable($proof['value']))->format('d.m.Y');if($proof['kind']==='amend_addr')$matched=$matched&&self::addressMatches($result,$proof['value']);if(in_array($proof['kind'],['amend_disc','clear_disc','add_disc'],true))$matched=$matched&&($proof['class'])::projectedMatches($result,$proof['intent']);if($matched)$confirmed[$id]['proved']=true;}}
        foreach($confirmed as$proof)if(!$proof['proved'])throw new \DomainException('bb_api_credit_mutation_requires_review');foreach($latest as$id){$proof=$confirmed[$id];if((int)$financialQuery['id']<=$id||(string)($financialResult[$proof['id_field']]??'')!==(string)$id||($financialResult[$proof['value_field']]??null)!==$proof['value']||($financialResult['account_evidence_hash']??null)!==$proof['hash']||($proof['kind']==='amend_addr'&&!self::addressMatches($financialResult,$proof['value']))||(in_array($proof['kind'],['amend_disc','clear_disc','add_disc'],true)&&!($proof['class'])::projectedMatches($financialResult,$proof['intent'])))throw new \DomainException('bb_api_credit_mutation_requires_review');}
    }
}
